        const topSkills = skills.slice(0, 4).map((s) => s.name);
        const topCompanies = Array.from(new Set(
          [...items]
            .sort((a, b) => (b.startDate ?? "").localeCompare(a.startDate ?? ""))
            .map((i) => i.company)
            .filter(Boolean)
        )).slice(0, 3);
