          <div
            className="w-full max-w-2xl rounded-2xl bg-background border shadow-2xl overflow-hidden animate-in slide-in-from-top-4 duration-200"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center gap-2 px-4 py-3 border-b">
              <SearchIcon className="h-4 w-4 text-muted-foreground shrink-0" />
              <input
                type="text"
                autoFocus
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                onKeyDown={(e) => {
                  if (flatHits.length === 0) return;
                  if (e.key === "ArrowDown") {
                    e.preventDefault();
                    setSearchSelectedIndex((i) => Math.min(i + 1, flatHits.length - 1));
                  } else if (e.key === "ArrowUp") {
                    e.preventDefault();
                    setSearchSelectedIndex((i) => Math.max(i - 1, 0));
                  } else if (e.key === "Enter") {
                    e.preventDefault();
                    const h = flatHits[searchSelectedIndex];
                    if (h) focusHit(h);
                  }
                }}
                placeholder={`Search ${profile?.fullName?.split(" ")[0] || "this candidate"}'s experience, skills, tools…`}
                className="flex-1 bg-transparent border-0 outline-none text-sm placeholder:text-muted-foreground"
              />
              {searchQuery && (
                <button
                  type="button"
                  onClick={() => setSearchQuery("")}
                  className="text-muted-foreground hover:text-foreground"
                  title="Clear"
                >
                  <X className="h-4 w-4" />
                </button>
              )}
              <kbd className="hidden sm:inline-flex items-center rounded border bg-muted/60 px-1.5 py-0.5 text-[10px] font-mono text-muted-foreground">
                Esc
              </kbd>
            </div>

            {/* Results */}
            <div className="max-h-[60vh] overflow-y-auto">
              {searchQuery.trim().length < 2 ? (
                <div className="px-4 py-6 text-sm text-muted-foreground">
                  {recentChips.length > 0 && (
                    <div className="mb-4">
                      <div className="text-[10px] font-semibold uppercase tracking-wider mb-2 opacity-70">Recent</div>
                      <div className="flex flex-wrap gap-1.5">
                        {recentChips.map((q) => (
                          <button
                            key={`recent-${q}`}
                            type="button"
                            onClick={() => setSearchQuery(q)}
                            className="inline-flex items-center gap-1 rounded-full border bg-muted/40 hover:bg-muted px-2.5 py-1 text-xs text-foreground transition"
